use std::env;
use std::process;

fn main() {
    let args: Vec<String> = env::args().collect();

    // Get the program name
    let prog_name = args.get(0)
        .and_then(|s| s.split('/').last())
        .unwrap_or("sox");

    if args.len() == 1 {
        // No arguments
        eprintln!("{} FAIL sox: No input filenames specified\n", prog_name);
        print_help();
        process::exit(1);
    }

    let first_arg = &args[1];

    match first_arg.as_str() {
        "--version" => {
            println!("{}:      SoX v14.4.2", prog_name);
            process::exit(0);
        }
        "--help" | "-h" => {
            print_help();
            process::exit(0);
        }
        "--info" | "--i" => {
            print_soxi_help();
            process::exit(0);
        }
        "--help-effect" => {
            if args.len() > 2 {
                handle_help_effect(&args[2], prog_name);
            } else {
                eprintln!("{}:      SoX v14.4.2", prog_name);
                eprintln!("--help-effect requires an effect name");
                process::exit(1);
            }
            process::exit(1);
        }
        "--help-format" => {
            if args.len() > 2 {
                handle_help_format(&args[2], prog_name);
            } else {
                eprintln!("{}:      SoX v14.4.2", prog_name);
                eprintln!("--help-format requires a format name");
                process::exit(1);
            }
            process::exit(1);
        }
        _ => {
            eprintln!("{} FAIL sox: Invalid argument or file", prog_name);
            print_help();
            process::exit(1);
        }
    }
}

fn print_help() {
    println!("./executable:      SoX v14.4.2\n");
    println!("Usage summary: [gopts] [[fopts] infile]... [fopts] outfile [effect [effopt]]...\n");
    // ... rest of help
}

fn print_soxi_help() {
    println!("./executable:      SoX v14.4.2\n");
    println!("Usage: soxi [-V[level]] [-T] [-t|-r|-c|-s|-d|-D|-b|-B|-p|-e|-a] infile1 ...\n");
    // ... rest of help
}

fn handle_help_effect(effect_name: &str, prog_name: &str) {
    // Handle specific effect help
    println!("{}:      SoX v14.4.2\n", prog_name);
    match effect_name {
        "gain" => {
            println!("Effect usage:\n");
            println!("gain [-e|-b|-B|-r] [-n] [-l|-h] [gain-dB]");
            println!("-e\t Equalise channels: peak to that with max peak;");
            println!("-B\t Balance channels: rms to that with max rms; no clip protection");
            println!("-b\t Balance channels: rms to that with max rms; clip protection");
            println!("\t   Note -Bn = -bn");
            println!("-r\t Reclaim headroom (as much as possible without clipping); see -h");
            println!("-n\t Norm file to 0dBfs(output precision); gain-dB, if present, usually <0");
            println!("-l\t Use simple limiter");
            println!("-h\t Apply attenuation for headroom for subsequent effects; gain-dB, if");
            println!("\t   present, is subject to reclaim by a subsequent gain -r");
            println!("gain-dB\t Apply gain in dB\n\n");
        }
        _ => {
            eprintln!("Cannot find an effect called `{}'.", effect_name);
            eprintln!("EFFECTS: allpass band bandpass bandreject bass bend biquad chorus channels compand contrast dcshift deemph delay dither divide+ downsample earwax echo echos equalizer fade fir firfit+ flanger gain highpass hilbert input# ladspa loudness lowpass mcompand noiseprof noisered norm oops output# overdrive pad phaser pitch rate remix repeat reverb reverse riaa silence sinc speed splice stat stats stretch swap synth tempo treble tremolo trim upsample vad vol");
            eprintln!("  * Deprecated effect    + Experimental effect    # LibSoX-only effect");
        }
    }
}

fn handle_help_format(format_name: &str, prog_name: &str) {
    println!("{}:      SoX v14.4.2\n", prog_name);
    match format_name {
        "wav" => {
            println!("Format: wav");
            println!("Description: Microsoft audio format");
            println!("Also handles: wavpcm amb");
            println!("Reads: yes");
            println!("Writes:");
            println!("  16-bit Signed Integer PCM (16-bit precision)");
            println!("  24-bit Signed Integer PCM (24-bit precision)");
            println!("  32-bit Signed Integer PCM (32-bit precision)");
            println!("   8-bit Unsigned Integer PCM (8-bit precision)");
            println!("   8-bit u-law (14-bit precision)");
            println!("   8-bit A-law (13-bit precision)");
            println!("   4-bit MS ADPCM (14-bit precision)");
            println!("   4-bit IMA ADPCM (13-bit precision)");
            println!("  32-bit Floating Point PCM (25-bit precision)");
            println!("  64-bit Floating Point PCM (54-bit precision)");
        }
        _ => {
            eprintln!("Cannot find a format called `{}'.", format_name);
            eprintln!("AUDIO FILE FORMATS: 8svx aif aifc aiff aiffc al amb au avr cdda cdr cvs cvsd cvu dat dvms f32 f4 f64 f8 fssd gsrt hcom htk ima ircam la lpc lpc10 lu maud nist prc raw s1 s16 s2 s24 s3 s32 s4 s8 sb sf sl sln smp snd sndr sndt sou sox sph sw txw u1 u16 u2 u24 u3 u32 u4 u8 ub ul uw vms voc vox wav wavpcm wve xa");
            eprintln!("PLAYLIST FORMATS: m3u pls");
            eprintln!("AUDIO DEVICE DRIVERS: oss ossdsp\n");
        }
    }
}
